using JTradeERP.Application.Common.Security;using JTradeERP.Domain.Security;using MediatR;namespace JTradeERP.Application.Features.Billing.NumberSeries.GetNumberSeriesById;public static class GetNumberSeriesByIdEndPoint{public static void Map(IEndpointRouteBuilder e)=>e.MapGet("/number-series/{id:guid}",(Guid id,ISender s,CancellationToken ct)=>s.Send(new GetNumberSeriesByIdQuery(id),ct)).RequirePermission("Admin.NumberSeries.Manage",Capability.View);}
